content.text:
{
  "name": "软件位操作 SPI 接口",
  "name_en": "Software Bit-Banged SPI Interface",
  "manufacturer": "",
  "description": "一种非物理的软件组件，通过 GPIO 以位操作方式实现本地 SPI 通信接口，可在实验控制与原型开发中与 SPI 外设进行基础数据交换。它依赖软件时序而非专用硬件 SPI 控制器，适合本地简易通信，不适合需要高性能或远程稳定事务处理的场景。",
  "description_en": "A non-physical software component that implements a local SPI communication interface by bit-banging GPIO pins. It is useful in lab control and prototyping for basic data exchange with SPI peripherals. It relies on software timing instead of a dedicated hardware SPI controller, making it suitable for simple local communication rather than high-performance or remote transaction handling.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该软件 SPI 接口并释放相关资源。",
      "description_en": "Close the software SPI interface and release associated resources."
    },
    {
      "action_name": "auto-transfer",
      "description": "通过该软件 SPI 接口执行一次数据传输。",
      "description_en": "Perform a data transfer through the software SPI interface."
    },
    {
      "action_name": "auto-closed",
      "description": "获取该软件 SPI 接口是否已关闭。",
      "description_en": "Get whether the software SPI interface is closed."
    }
  ],
  "tag_hints": [
    "software SPI",
    "bit-banged GPIO",
    "local SPI communication",
    "SPI bus emulation",
    "GPIO pin sharing",
    "instrument prototyping"
  ]
}

